AND TENANT_ID = #{tenantId,jdbcType=VARCHAR}

  AND INVOCATION_ID = #{invocationId,jdbcType=VARCHAR}


  AND PROCESS_INSTANCE_ID = #{processInstanceId,jdbcType=VARCHAR}


  AND PROCESS_DEF_ID = #{processDefId,jdbcType=VARCHAR}


  AND VERSION_NO = #{versionNo,jdbcType=INTEGER}


  AND STATUS = #{status,jdbcType=VARCHAR}

mapper.delete:
DELETE FROM fm_system_task_execution
WHERE OID = #{oid,jdbcType=CHAR}
  AND TENANT_ID = #{tenantId,jdbcType=VARCHAR}
  AND 1 = 0

mapper.update:
UPDATE fm_system_task_execution
SET STATUS = 'RUNNING',
    GENERATION = GENERATION + 1,
    ATTEMPT_NO = ATTEMPT_NO + 1,
    LEASE_UNTIL = #{leaseUntil,jdbcType=TIMESTAMP}
WHERE TENANT_ID = #{tenantId,jdbcType=VARCHAR}
  AND OID = #{oid,jdbcType=CHAR}
  AND STATUS = 'READY'
  AND GENERATION = #{generation,jdbcType=INTEGER}
  AND ATTEMPT_NO BETWEEN 0 AND 2
  AND (NEXT_ATTEMPT_AT IS NULL OR NEXT_ATTEMPT_AT <= #{now,jdbcType=TIMESTAMP})

UPDATE fm_system_task_execution
SET STATUS = 'SUCCEEDED',
    RESULT_SHA256 = #{resultSha256,jdbcType=CHAR},
    FORM_SNAPSHOT_OID = #{formSnapshotOid,jdbcType=CHAR},
    COMPLETED_AT = #{now,jdbcType=TIMESTAMP},
    LEASE_UNTIL = NULL
WHERE TENANT_ID = #{tenantId,jdbcType=VARCHAR}
  AND OID = #{oid,jdbcType=CHAR}
  AND STATUS = 'RUNNING'
  AND GENERATION = #{generation,jdbcType=INTEGER}
  AND LEASE_UNTIL > #{now,jdbcType=TIMESTAMP}

mapper.select:
SELECT 
FROM fm_system_task_execution
WHERE TENANT_ID = #{tenantId,jdbcType=VARCHAR}
  AND INVOCATION_ID = #{invocationId,jdbcType=VARCHAR}
FOR UPDATE

mapper.update:
UPDATE fm_system_task_execution
SET STATUS = 'FAILED',
    ERROR_CODE = #{errorCode,jdbcType=VARCHAR},
    INCIDENT_OID = COALESCE(INCIDENT_OID, OID),
    COMPLETED_AT = #{now,jdbcType=TIMESTAMP},
    LEASE_UNTIL = NULL
WHERE TENANT_ID = #{tenantId,jdbcType=VARCHAR}
  AND OID = #{oid,jdbcType=CHAR}
  AND STATUS = 'RUNNING'
  AND GENERATION = #{generation,jdbcType=INTEGER}

mapper.select:
SELECT 
FROM fm_system_task_execution
WHERE TENANT_ID = #{tenantId,jdbcType=VARCHAR}
  AND TASK_TYPE = 'GROOVY'
  AND STATUS = 'RUNNING'
  AND LEASE_UNTIL <= #{now,jdbcType=TIMESTAMP}
ORDER BY LEASE_UNTIL, OID
LIMIT #{limit,jdbcType=INTEGER}

mapper.update:
UPDATE fm_system_task_execution
SET STATUS = 'FAILED',
    ERROR_CODE = 'GROOVY_LEASE_EXPIRED',
    INCIDENT_OID = COALESCE(INCIDENT_OID, OID),
    COMPLETED_AT = #{now,jdbcType=TIMESTAMP},
    LEASE_UNTIL = NULL
WHERE TENANT_ID = #{tenantId,jdbcType=VARCHAR}
  AND OID = #{oid,jdbcType=CHAR}
  AND TASK_TYPE = 'GROOVY'
  AND STATUS = 'RUNNING'
  AND GENERATION = #{generation,jdbcType=INTEGER}
  AND LEASE_UNTIL <= #{now,jdbcType=TIMESTAMP}

UPDATE fm_system_task_execution
SET STATUS = 'READY', GENERATION = GENERATION + 1, COMPLETED_AT = NULL,
    NEXT_ATTEMPT_AT = #{now,jdbcType=TIMESTAMP}, INCIDENT_OID = COALESCE(INCIDENT_OID, OID)
WHERE TENANT_ID = #{tenantId,jdbcType=VARCHAR}
  AND OID = #{oid,jdbcType=CHAR}
  AND TASK_TYPE = 'GROOVY' AND STATUS = 'FAILED'
  AND GENERATION = #{generation,jdbcType=INTEGER}
  AND ATTEMPT_NO BETWEEN 0 AND 2
  AND LEASE_UNTIL IS NULL AND COMPLETED_AT IS NOT NULL
  AND RESULT_SHA256 IS NULL AND FORM_SNAPSHOT_OID IS NULL
  AND NOT EXISTS (
    SELECT 1 FROM fm_system_task_attempt a
    WHERE a.TENANT_ID = #{tenantId,jdbcType=VARCHAR} AND a.EXECUTION_OID = #{oid,jdbcType=CHAR}
      AND a.STATUS = 'RUNNING'
  )

mapper.select:
SELECT OID, TENANT_ID, INVOCATION_ID, GENERATION FROM fm_system_task_execution WHERE TENANT_ID = #{tenantId,jdbcType=VARCHAR} AND TASK_TYPE = 'GROOVY' AND STATUS = 'FAILED' AND ERROR_CODE IN ('GROOVY_RUNTIME_BUSY', 'GROOVY_RUNTIME_START_UNAVAILABLE') AND LEASE_UNTIL IS NULL AND RESULT_SHA256 IS NULL AND FORM_SNAPSHOT_OID IS NULL AND ( (ATTEMPT_NO = 1 AND COMPLETED_AT <= #{firstCutoff,jdbcType=TIMESTAMP}) OR (ATTEMPT_NO = 2 AND COMPLETED_AT <= #{secondCutoff,jdbcType=TIMESTAMP}) )
AND OID > #{afterOid,jdbcType=CHAR}
ORDER BY OID LIMIT #{limit,jdbcType=INTEGER}

SELECT OID, TENANT_ID, INVOCATION_ID, GENERATION
FROM fm_system_task_execution
WHERE TENANT_ID = #{tenantId,jdbcType=VARCHAR} AND TASK_TYPE = 'GROOVY' AND STATUS = 'READY'
  AND COALESCE(NEXT_ATTEMPT_AT, STARTED_AT) <= #{cutoff,jdbcType=TIMESTAMP}

  AND OID > #{afterOid,jdbcType=CHAR}

ORDER BY OID
LIMIT #{limit,jdbcType=INTEGER}

mapper.update:
UPDATE fm_system_task_execution
SET STATUS = #{status,jdbcType=VARCHAR}, GENERATION = GENERATION + 1,
    ERROR_CODE = #{errorCode,jdbcType=VARCHAR}, INCIDENT_OID = COALESCE(INCIDENT_OID, OID),
    COMPLETED_AT = #{now,jdbcType=TIMESTAMP}, NEXT_ATTEMPT_AT = NULL
WHERE TENANT_ID = #{tenantId,jdbcType=VARCHAR} AND OID = #{oid,jdbcType=CHAR}
  AND TASK_TYPE = 'GROOVY' AND STATUS = 'READY' AND GENERATION = #{generation,jdbcType=INTEGER}
  AND COALESCE(NEXT_ATTEMPT_AT, STARTED_AT) <= #{cutoff,jdbcType=TIMESTAMP}
  AND LEASE_UNTIL IS NULL AND COMPLETED_AT IS NULL AND RESULT_SHA256 IS NULL AND FORM_SNAPSHOT_OID IS NULL
  AND NOT EXISTS (
    SELECT 1 FROM fm_system_task_attempt a
    WHERE a.TENANT_ID = #{tenantId,jdbcType=VARCHAR} AND a.EXECUTION_OID = #{oid,jdbcType=CHAR}
      AND a.STATUS = 'RUNNING'
  )

mapper.select:
SELECT OID, TENANT_ID, INCIDENT_OID, INVOCATION_ID, PARENT_INVOCATION_ID, PROCESS_INSTANCE_ID,
       PROCESS_DEF_ID, VERSION_NO, NODE_ID, STATUS, ATTEMPT_NO,
       GENERATION, ERROR_CODE, STARTED_AT, COMPLETED_AT
FROM fm_system_task_execution
WHERE TENANT_ID = #{tenantId,jdbcType=VARCHAR}
  AND TASK_TYPE = 'GROOVY'
  AND (STATUS = 'FAILED' OR INCIDENT_OID IS NOT NULL OR PARENT_INVOCATION_ID IS NOT NULL)

  AND INVOCATION_ID = #{invocationId,jdbcType=VARCHAR}

ORDER BY COMPLETED_AT DESC, OID
LIMIT #{limit,jdbcType=INTEGER} OFFSET #{offset,jdbcType=INTEGER}
